//! 📦️ Typed PLY snapshot records retain scalar words, list order and declaration metadata.
use super::{PlySnapshot,PlyFormat,PlyElement,PlyProperty,PlyRow,PlyValue,PlyScalarType};
fn scalar_name(kind:PlyScalarType)->&'static str{match kind{PlyScalarType::Char=>"char",PlyScalarType::UChar=>"uchar",PlyScalarType::Short=>"short",PlyScalarType::UShort=>"ushort",PlyScalarType::Int=>"int",PlyScalarType::UInt=>"uint",PlyScalarType::Float=>"float",PlyScalarType::Double=>"double"}}
fn scalar_kind(value:&str)->Result<PlyScalarType,String>{match value{"char"=>Ok(PlyScalarType::Char),"uchar"=>Ok(PlyScalarType::UChar),"short"=>Ok(PlyScalarType::Short),"ushort"=>Ok(PlyScalarType::UShort),"int"=>Ok(PlyScalarType::Int),"uint"=>Ok(PlyScalarType::UInt),"float"=>Ok(PlyScalarType::Float),"double"=>Ok(PlyScalarType::Double),_=>Err("PLY snapshot scalar kind is unknown".into())}}
#[derive(dsl::DslRecord)]
struct Value{kind:String,integer_value:Option<i64>,float32_ieee754_bits:Option<u32>,float64_ieee754_bits:Option<u64>,list_values:Option<Vec<Value>>}
impl From<&PlyValue> for Value{fn from(value:&PlyValue)->Self{let mut result=Self{kind:String::new(),integer_value:None,float32_ieee754_bits:None,float64_ieee754_bits:None,list_values:None};match value{PlyValue::Char(value)=>{result.kind="char".into();result.integer_value=Some(i64::from(*value));},PlyValue::UChar(value)=>{result.kind="uchar".into();result.integer_value=Some(i64::from(*value));},PlyValue::Short(value)=>{result.kind="short".into();result.integer_value=Some(i64::from(*value));},PlyValue::UShort(value)=>{result.kind="ushort".into();result.integer_value=Some(i64::from(*value));},PlyValue::Int(value)=>{result.kind="int".into();result.integer_value=Some(i64::from(*value));},PlyValue::UInt(value)=>{result.kind="uint".into();result.integer_value=Some(i64::from(*value));},PlyValue::Float(value)=>{result.kind="float".into();result.float32_ieee754_bits=Some(value.to_bits());},PlyValue::Double(value)=>{result.kind="double".into();result.float64_ieee754_bits=Some(value.to_bits());},PlyValue::List(values)=>{result.kind="list".into();result.list_values=Some(values.iter().map(Value::from).collect());}}result}}
impl TryFrom<Value> for PlyValue{type Error=String;fn try_from(value:Value)->Result<Self,String>{let number=||value.integer_value.ok_or_else(||"PLY snapshot integer value missing".to_string());if usize::from(value.integer_value.is_some())+usize::from(value.float32_ieee754_bits.is_some())+usize::from(value.float64_ieee754_bits.is_some())+usize::from(value.list_values.is_some())!=1{return Err("PLY snapshot scalar must own exactly one typed payload".into());}match value.kind.as_str(){"char"=>Ok(Self::Char(i8::try_from(number()?).map_err(|error|error.to_string())?)),"uchar"=>Ok(Self::UChar(u8::try_from(number()?).map_err(|error|error.to_string())?)),"short"=>Ok(Self::Short(i16::try_from(number()?).map_err(|error|error.to_string())?)),"ushort"=>Ok(Self::UShort(u16::try_from(number()?).map_err(|error|error.to_string())?)),"int"=>Ok(Self::Int(i32::try_from(number()?).map_err(|error|error.to_string())?)),"uint"=>Ok(Self::UInt(u32::try_from(number()?).map_err(|error|error.to_string())?)),"float"=>Ok(Self::Float(f32::from_bits(value.float32_ieee754_bits.ok_or("PLY snapshot binary32 word missing")?))),"double"=>Ok(Self::Double(f64::from_bits(value.float64_ieee754_bits.ok_or("PLY snapshot binary64 word missing")?))),"list"=>Ok(Self::List(value.list_values.ok_or("PLY snapshot list missing")?.into_iter().map(PlyValue::try_from).collect::<Result<_,_>>()?)),_=>Err("PLY snapshot value kind unknown".into())}}}
#[derive(dsl::DslRecord)]
struct Property{name:String,form:String,scalar_kind:Option<String>,count_kind:Option<String>,value_kind:Option<String>}
impl From<&PlyProperty> for Property{fn from(value:&PlyProperty)->Self{match value{PlyProperty::Scalar{name,kind}=>Self{name:name.clone(),form:"scalar".into(),scalar_kind:Some(scalar_name(*kind).into()),count_kind:None,value_kind:None},PlyProperty::List{name,count_kind,value_kind}=>Self{name:name.clone(),form:"list".into(),scalar_kind:None,count_kind:Some(scalar_name(*count_kind).into()),value_kind:Some(scalar_name(*value_kind).into())}}}}
impl TryFrom<Property> for PlyProperty{type Error=String;fn try_from(value:Property)->Result<Self,String>{match value.form.as_str(){"scalar" if value.count_kind.is_none()&&value.value_kind.is_none()=>Ok(Self::Scalar{name:value.name,kind:scalar_kind(value.scalar_kind.as_deref().ok_or("PLY scalar declaration kind missing")?)?}),"list" if value.scalar_kind.is_none()=>Ok(Self::List{name:value.name,count_kind:scalar_kind(value.count_kind.as_deref().ok_or("PLY list count kind missing")?)?,value_kind:scalar_kind(value.value_kind.as_deref().ok_or("PLY list value kind missing")?)?}),_=>Err("PLY snapshot property form and typed fields differ".into())}}}
#[derive(dsl::DslRecord)]
struct Row{values:Vec<Value>}
#[derive(dsl::DslRecord)]
struct Element{name:String,count:u64,properties:Vec<Property>,rows:Vec<Row>}
#[derive(dsl::DslRecord)]
struct Snapshot{schema:String,format:String,comments:Vec<String>,elements:Vec<Element>}
impl From<&PlySnapshot> for Snapshot{fn from(value:&PlySnapshot)->Self{Self{schema:value.schema.clone(),format:match value.format{PlyFormat::Ascii=>"ascii",PlyFormat::BinaryLittleEndian=>"binaryLittleEndian",PlyFormat::BinaryBigEndian=>"binaryBigEndian"}.into(),comments:value.comments.clone(),elements:value.elements.iter().map(|value|Element{name:value.name.clone(),count:value.count,properties:value.properties.iter().map(Property::from).collect(),rows:value.rows.iter().map(|value|Row{values:value.values.iter().map(Value::from).collect()}).collect()}).collect()}}}
impl TryFrom<Snapshot> for PlySnapshot{type Error=String;fn try_from(value:Snapshot)->Result<Self,String>{Ok(Self{schema:value.schema,format:match value.format.as_str(){"ascii"=>PlyFormat::Ascii,"binaryLittleEndian"=>PlyFormat::BinaryLittleEndian,"binaryBigEndian"=>PlyFormat::BinaryBigEndian,_=>return Err("PLY snapshot format is unknown".into())},comments:value.comments,elements:value.elements.into_iter().map(|value|Ok(PlyElement{name:value.name,count:value.count,properties:value.properties.into_iter().map(PlyProperty::try_from).collect::<Result<_,_>>()?,rows:value.rows.into_iter().map(|value|Ok(PlyRow{values:value.values.into_iter().map(PlyValue::try_from).collect::<Result<_,String>>()?})).collect::<Result<_,String>>()?})).collect::<Result<_,String>>()?})}}
impl store::ArtifactDsl for PlySnapshot{
 const EXTENSION:&'static str="ply";
 fn envelope_id()->&'static str{"stdio.ply"}
 fn parse_dsl(text:&str)->Result<Self,store::TextError>{let body=store::semio_format::split_text_preamble(text).map(|(_,body)|body).unwrap_or(text);let record=dsl::parse(body,&Snapshot::__dsl_spec(),&dsl::ParseOptions{limits:dsl::Limits::default(),mode:dsl::SourceMode::Document})?;Self::try_from(Snapshot::__dsl_from_record(&record)?).map_err(|error|store::TextError::new(error,dsl::TextSpan::at(1,1)))}
 fn print_dsl(&self)->String{let snapshot=Snapshot::from(self);let body=dsl::print(&snapshot.__dsl_to_record(),&Snapshot::__dsl_spec(),dsl::JoinMode::Document);let envelope=store::semio_format::SemioEnvelope::from_envelope_id("stdio.ply",store::semio_format::Component::Dsl,1).expect("valid PLY snapshot identity");store::semio_format::wrap_text(&envelope,&body)}
}
impl store::ArtifactPack for PlySnapshot{
 fn sqlite_snapshot_codec()->Option<store::ArtifactSqliteSnapshotCodec>{Some(<Self as store::ArtifactSqliteSnapshot>::sqlite_codec())}
 fn encode_pack_with(&self,options:&store::PackEncodeOptions)->Result<Vec<u8>,store::PackError>{let snapshot=Snapshot::from(self);let inner=store::pack_rt::encode_document(&Snapshot::__dsl_spec(),&snapshot.__dsl_to_record(),options)?;let envelope=store::semio_format::SemioEnvelope::from_envelope_id("stdio.ply",store::semio_format::Component::Pack,1).map_err(|error|store::PackError::Schema(error.to_string()))?;Ok(store::semio_format::wrap_binary(&envelope,&inner))}
 fn decode_pack_with(bytes:&[u8],options:&store::PackDecodeOptions)->Result<Self,store::PackError>{let(envelope,inner)=store::semio_format::unwrap_binary(bytes).map_err(|error|store::PackError::Schema(error.to_string()))?;if !envelope.matches_identity("stdio.ply",store::semio_format::Component::Pack,1){return Err(store::PackError::Schema("PLY snapshot pack identity differs".into()));}let(record,_)=store::pack_rt::decode_document(&inner,&Snapshot::__dsl_spec(),options)?;Self::try_from(Snapshot::__dsl_from_record(&record).map_err(store::text_error_to_pack_error)?).map_err(store::PackError::Schema)}
 fn record_spec()->Option<dsl::RecordSpec>{Some(Snapshot::__dsl_spec())}
}
